# /etc/systemd/system/nxeon-web.service.d/override.conf
[Service]
User=nxeon
Group=nxeon

# /etc/systemd/system/nxeon-worker.service
# Nxeon provisioning worker — systemd unit TEMPLATE (install at
# /etc/systemd/system/nxeon-worker.service, then `systemctl daemon-reload`).
#
# Why these stop settings matter (2026-10-01): the worker drains gracefully on
# SIGTERM — it stops claiming, waits WORKER_DRAIN_TIMEOUT_MS (default 60s) for
# in-flight jobs to finish, then hands the rest back to the queue with their
# attempt uncharged so the next process resumes them. systemd's default
# TimeoutStopSec (90s) would SIGKILL it mid-drain if a job writes slowly, and
# KillMode=control-group would kill child processes (sshpass/ssh) under a job
# before the drain gets to requeue it. Keep TimeoutStopSec > drain budget.
[Unit]
Description=Nxeon provisioning worker
After=network.target postgresql.service pve-cluster.service
Wants=postgresql.service
OnFailure=nxeon-alert@%n.service

[Service]
WorkingDirectory=/opt/nxeon
EnvironmentFile=/opt/nxeon/.env
Environment=NODE_ENV=production
ExecStart=/usr/bin/npx tsx worker/index.ts
Restart=always
RestartSec=5
KillSignal=SIGTERM
KillMode=mixed
TimeoutStopSec=120

[Install]
WantedBy=multi-user.target

# /etc/systemd/system/nxeon-worker.service.d/onfailure.conf
[Unit]
OnFailure=nxeon-alert@%n.service

# /etc/systemd/system/nxeon-staging-web.service
